package rules

import (
	"cmp"
	"fmt"
	"math"
	"slices"
	"strconv"
	"strings"
)

// The parser is a recursive descent over the lexer's tokens, with the official compiler's
// syntax errors as hidane measured them on the emulator (hidane
// crates/hidane-rules/src/parser.rs and tests/fixtures/rules_compile.json). The official
// compiler is generated by ANTLR, and its messages come from three places:
//
//   - ANTLR's recovery: "mismatched input 'x' expecting {…}" and "missing 'x' at 'y'", which
//     put the parser in recovery mode (no other such error is reported until a token is
//     matched), and "Unexpected 'x'." where ANTLR would say "extraneous input" or "no viable
//     alternative". After an error the parser skips to a token that can follow, as ANTLR does.
//     These stop the compiler: a file with one is not checked further (parse returns no file).
//   - The grammar's own error alternatives, reported wherever they are parsed: "Missing 'if'
//     before conditional expression.", "The 'match' body must contain at least one
//     declaration.", … The file is still checked.
//   - The lexer's "token recognition error at: 'x'". The compiler parses twice, a fast pass
//     that stops at the first syntax error and then a pass with recovery, and keeps the tokens
//     of the first: a lexer error before the first syntax error is not reported when there is
//     one.
//
// Lines after the first error do not always match the compiler's, which depend on ANTLR's
// prediction; the first error does in every case hidane recorded.
//
// The precedence of operators is production's, which differs from the documentation's table
// (Rules Test API probes, S1-A review): from the tightest, a[i] a() a.f, then ! -, then * / %,
// then + -, then < <= > >=, then == !=, then is, then in, then &&, then ||, then ?:. All are
// left-associative but ?:, whose branches may be conditionals themselves. They are read by
// precedence climbing, as ANTLR reads a left-recursive rule, and "x is T" is a postfix of its
// level: any operator may follow it, so "1 is int < 2" is ((1 is int) < 2).
//
// Nesting is checked once a file parses (ADR-021 §2.1, §4): an expression nested
// lim.ExpressionDepth+1 deep (99) is "Expression is too complex to evaluate safely.", reported
// at every node and parenthesis at exactly that depth, as the emulator does. A chain of member
// accesses, calls and indexes longer than lim.MemberChain is the same error, an Aruma limit.

// Messages of the parser's own, copied from the oracle. The ones shared with the checker are in
// issues.go.
const (
	msgEmptyContent      = "Rules content empty. Compilation aborted."
	msgMissingMatch      = "Missing 'match' keyword before path."
	msgSlashInPath       = "Forward slash '/' found where identifier or binding expected."
	msgEmptyMatch        = "The 'match' body must contain at least one declaration."
	msgEmptyService      = "The 'service' body must contain at least one declaration."
	msgDuplicateService  = "Duplicate service name declaration."
	msgNoOperation       = "Expected at least one 'operation' after 'allow'."
	msgMissingIf         = "Missing 'if' before conditional expression."
	msgMissingColon      = "Missing ':' before 'if' condition."
	msgMissingCondition  = "Missing conditional expression after 'if'."
	msgFunctionNoID      = "Missing 'function' id"
	msgFunctionNoSig     = "Missing 'function' signature"
	msgFunctionNoBody    = "Missing 'function' body"
	msgIncrement         = "Increment (++) and decrement (--) operators are not supported."
	msgUnclosedString    = "Missing a closing %c"
	msgIsType            = "An unsupported type identifier was used with the 'is' operator. Received %s. Expected one of %s"
	msgImport            = "Import statements are not allowed."
	msgImportModule      = `Module "%s" is not part of the standard library.`
	msgInvalidNumber     = "Invalid number literal %s."
	msgTokenRecognition  = "token recognition error at: '%s'"
	expectExpression     = "{'--', '++', '{', '[', '(', '-', '!', '/', 'false', 'null', 'true', PATH_SEGMENT, IDENTIFIER, NUM_INT, NUM_FLOAT, UNPAIRED_DOUBLE_QUOTE, UNPAIRED_SINGLE_QUOTE, STRING, BYTES}"
	expectNegated        = "{'{', '[', '(', '/', 'false', 'null', 'true', PATH_SEGMENT, IDENTIFIER, NUM_INT, NUM_FLOAT, UNPAIRED_DOUBLE_QUOTE, UNPAIRED_SINGLE_QUOTE, STRING, BYTES}"
	expectPathNext       = "{'{', '/', PATH_SEGMENT}"
	expectAfterLetValue  = "{'&&', '.', '==', '>', '>=', '[', '<', '<=', '-', '%', '!=', '||', '+', ';', '/', '*', '?', 'in', 'is'}"
	expectAfterThen      = "{'&&', ':', '.', '==', '>', '>=', '[', '<', '<=', '-', '%', '!=', '||', '+', '/', '*', '?', 'in', 'is'}"
	expectTopWithVersion = "{'function', 'import', 'service'}"
	expectTop            = "{'function', 'import', 'service', 'rules_version'}"
)

// parseIsTypes are the type names "is" accepts, in the order the message lists them.
var parseIsTypes = []string{"bool", "bytes", "constraint", "duration", "float", "int", "latlng", "list",
	"vector", "set", "number", "map", "string", "timestamp", "path", "map_diff"}

// parsePackages are the namespaces of library functions, math.abs(x): the depth check does not
// count them as receivers, as they are no values.
var parsePackages = map[string]bool{"math": true, "duration": true, "timestamp": true, "latlng": true, "hashing": true}

// Bounds that keep the parser and the depth check within their stack. The compiler refuses far
// less (nesting 99, ADR-021 §4), which the depth check reports; past these the statement or the
// file is not read further.
const (
	parseMaxNesting   = 1000    // expressions inside expressions
	parseMaxOperators = 100_000 // operators of one level in a row, a && b && …
	parseMaxBodies    = 1000    // match blocks inside match blocks
)

// tk is a token as the parser tells them apart: an operator or punctuation mark (its token's
// value), a lexical class, or a keyword.
type tk uint8

const (
	tkLParen     = tk(tokLParen)
	tkRParen     = tk(tokRParen)
	tkLBrack     = tk(tokLBrack)
	tkRBrack     = tk(tokRBrack)
	tkLBrace     = tk(tokLBrace)
	tkRBrace     = tk(tokRBrace)
	tkComma      = tk(tokComma)
	tkDot        = tk(tokDot)
	tkColon      = tk(tokColon)
	tkSemicolon  = tk(tokSemicolon)
	tkQuestion   = tk(tokQuestion)
	tkAssign     = tk(tokAssign)
	tkNot        = tk(tokNot)
	tkMinus      = tk(tokMinus)
	tkSlash      = tk(tokSlash)
	tkIncrement  = tk(tokIncrement)
	tkDecrement  = tk(tokDecrement)
	tkClassStart = tk(64)
)

const (
	tkEOF tk = tkClassStart + iota
	tkIdent
	tkInt
	tkFloat
	tkString
	tkBytes
	tkUnpairedSingle
	tkUnpairedDouble
	tkSegment
	tkDollar
	tkAt

	// Keywords, CEL's reserved words among them: no variable, function or method may be
	// named so, a field may (but rules_version).
	tkAllow
	tkFalse
	tkFunction
	tkIf
	tkImport
	tkIn
	tkIs
	tkLet
	tkMatch
	tkNull
	tkReturn
	tkRulesVersion
	tkService
	tkTrue
	tkBreak
	tkContinue
	tkElse
	tkFor
	tkPackage
	tkVar
	tkWhile
)

var parseKeywords = map[string]tk{
	"allow": tkAllow, "false": tkFalse, "function": tkFunction, "if": tkIf, "import": tkImport,
	"in": tkIn, "is": tkIs, "let": tkLet, "match": tkMatch, "null": tkNull, "return": tkReturn,
	"rules_version": tkRulesVersion, "service": tkService, "true": tkTrue, "break": tkBreak,
	"continue": tkContinue, "else": tkElse, "for": tkFor, "package": tkPackage, "var": tkVar,
	"while": tkWhile,
}

// display names the token as ANTLR does in "expecting …" and "missing … at".
func (t tk) display() string {
	switch t {
	case tkIdent:
		return "IDENTIFIER"
	case tkString:
		return "STRING"
	}
	return "'" + token(t).String() + "'"
}

// isWord is an identifier or a keyword.
func (t tk) isWord() bool { return t == tkIdent || t >= tkAllow }

// startsPrimary is a token a primary expression may start with.
func (t tk) startsPrimary() bool {
	switch t {
	case tkLBrace, tkLBrack, tkLParen, tkSlash, tkFalse, tkNull, tkTrue, tkSegment, tkIdent,
		tkInt, tkFloat, tkUnpairedDouble, tkUnpairedSingle, tkString, tkBytes:
		return true
	}
	return false
}

// startsExpression is a token an expression may start with.
func (t tk) startsExpression() bool {
	return t == tkDecrement || t == tkIncrement || t == tkMinus || t == tkNot || t.startsPrimary()
}

// binaryOp is an operator that joins two operands (but is).
func (t tk) binaryOp() bool {
	switch token(t) {
	case tokOr, tokAnd, tokEQ, tokNE, tokLT, tokLE, tokGT, tokGE, tokPlus, tokMinus, tokStar, tokSlash, tokPercent:
		return true
	}
	return t == tkIn
}

// startsTop is a token a declaration of the file starts with, or the end.
func (t tk) startsTop() bool {
	return t == tkFunction || t == tkImport || t == tkService || t == tkEOF
}

// place is where declarations are: what they may be and where recovery stops.
type place uint8

const (
	inService place = iota
	inMatch
)

// starts is a token a declaration starts with here.
func (pl place) starts(t tk) bool {
	return t == tkFunction || t == tkMatch || t == tkSegment || t == tkSlash || pl == inMatch && t == tkAllow
}

// stops is where skipping after an error stops: what may follow a declaration here or in an
// enclosing scope.
func (pl place) stops(t tk) bool {
	return pl.starts(t) || t == tkRBrace || t == tkImport || t == tkService || t == tkEOF
}

// finding is an issue before its position is known.
type finding struct {
	at  span
	msg string
}

type parser struct {
	src  string
	lim  Limits
	toks []lexeme
	kind []tk // what the parser sees of each token
	i    int  // the current token

	found []finding // syntax and grammar errors, in the order found
	// late are what the compiler reports only of a file without syntax errors: numbers out of
	// range, nesting too deep and a service declared twice.
	late []finding

	recovering  bool // ANTLR's recovery mode: set by a reported mismatch, cleared by a match
	failure     int  // the token of the first syntax error, or -1
	syntaxError bool // the compiler stops after parsing
	gaveUp      bool // the file nests too deep to read further: no more syntax errors
	abort       bool // give the statement up: an error inside brackets, or too deep to read
	nesting     int  // brackets open in the expression
	nest        int  // expressions inside expressions, for parseMaxNesting
	bodies      int  // match blocks inside match blocks, for parseMaxBodies

	// parens are the opening parentheses around each expression, outermost first. The tree
	// leaves them out, but they count towards an expression's depth.
	parens map[expr][]span
	// roots are the expressions of the statements, for the depth check.
	roots []expr
}

// parse reads a rules file into its tree, and reports every syntax error it finds, recovering
// at ; and }. It returns no file when the file is empty or has a syntax error that stops the
// compiler: then nothing more is checked, as the compiler checks nothing more. Errors of the
// grammar's own ("Missing 'if' before conditional expression.") and of the lexer leave the
// file to be checked. Nesting deeper than lim.ExpressionDepth and member chains longer than
// lim.MemberChain are errors ("Expression is too complex to evaluate safely."). The issues are
// in source order.
func parse(name, src string, lim Limits) (*file, []Issue) {
	if src == "" {
		return nil, []Issue{{File: name, Severity: SeverityError, Description: msgEmptyContent}}
	}
	toks, lexErrors := lex(src)
	p := &parser{src: src, lim: lim, toks: toks, kind: make([]tk, len(toks)), failure: -1, parens: map[expr][]span{}}
	for i, t := range toks {
		p.kind[i] = p.classify(t)
	}
	f := p.file()
	f.name, f.src = name, src

	// Lexer errors are reported when the fast pass did not stop, or past the token it stopped
	// at (the second pass lexes them).
	frontier := -1
	if p.failure >= 0 {
		frontier = p.toks[p.failure].end
	}
	for _, e := range lexErrors {
		if frontier < 0 || e.start >= frontier {
			p.found = append(p.found, finding{e.span, fmt.Sprintf(msgTokenRecognition, e.text)})
		}
	}
	if p.syntaxError {
		return nil, p.issues(name, p.found)
	}
	for _, root := range p.roots {
		p.checkDepth(root)
	}
	return f, p.issues(name, append(p.found, p.late...))
}

// classify tells keywords and operators apart.
func (p *parser) classify(t lexeme) tk {
	switch t.kind {
	case lexOp:
		return tk(t.op)
	case lexIdent:
		if k, ok := parseKeywords[p.src[t.start:t.end]]; ok {
			return k
		}
		return tkIdent
	case lexInt:
		return tkInt
	case lexFloat:
		return tkFloat
	case lexString:
		return tkString
	case lexBytes:
		return tkBytes
	case lexUnpaired:
		if p.src[t.start] == '\'' {
			return tkUnpairedSingle
		}
		return tkUnpairedDouble
	case lexSegment:
		return tkSegment
	case lexDollar:
		return tkDollar
	case lexAt:
		return tkAt
	}
	return tkEOF
}

// issues sorts the findings by position and then text, as the compiler lists them, and gives
// them their positions.
func (p *parser) issues(name string, found []finding) []Issue {
	slices.SortStableFunc(found, func(a, b finding) int {
		return cmp.Or(cmp.Compare(a.at.start, b.at.start), strings.Compare(a.msg, b.msg))
	})
	cur := newPosCursor(p.src)
	issues := make([]Issue, len(found))
	for i, f := range found {
		pos := cur.at(f.at)
		issues[i] = Issue{File: name, Position: &pos, Severity: SeverityError, Description: f.msg}
	}
	return issues
}

// ----- tokens

// la returns the k-th token from here (1 is the current one).
func (p *parser) la(k int) tk { return p.kind[min(p.i+k-1, len(p.kind)-1)] }

func (p *parser) tok(k int) lexeme { return p.toks[min(p.i+k-1, len(p.toks)-1)] }

func (p *parser) text(t lexeme) string {
	if t.kind == lexEOF {
		return "<EOF>"
	}
	return p.src[t.start:t.end]
}

// quoted is the token as ANTLR quotes it in messages.
func (p *parser) quoted(t lexeme) string {
	return "'" + lexSpelled.Replace(p.text(t)) + "'"
}

// bump matches the current token.
func (p *parser) bump() lexeme {
	t := p.tok(1)
	if t.kind != lexEOF {
		p.i++
	}
	p.recovering = false
	return t
}

// skip passes the current token over while recovering.
func (p *parser) skip() {
	if p.la(1) != tkEOF {
		p.i++
	}
}

func (p *parser) skipUntil(stop func(tk) bool) {
	for p.la(1) != tkEOF && !stop(p.la(1)) {
		p.i++
	}
}

// from is the span from start to the end of the last token passed.
func (p *parser) from(start int) span {
	end := start
	if p.i > 0 {
		end = max(end, p.toks[p.i-1].end)
	}
	return span{start, end}
}

// ----- errors

func (p *parser) failAt(k int) {
	if p.gaveUp {
		return
	}
	at := min(p.i+k-1, len(p.toks)-1)
	if p.failure < 0 || at < p.failure {
		p.failure = at
	}
	p.syntaxError = true
}

func (p *parser) report(at span, msg string) {
	if !p.gaveUp {
		p.found = append(p.found, finding{at, msg})
	}
}

// unexpected reports "Unexpected 'x'." where ANTLR deletes an extraneous token or skips one in
// a loop: it does not enter recovery mode.
func (p *parser) unexpected(k int) {
	p.failAt(k)
	if !p.recovering {
		t := p.tok(k)
		p.report(t.span, "Unexpected "+p.quoted(t)+".")
	}
}

// noViable reports "Unexpected 'x'." where ANTLR finds no viable alternative.
func (p *parser) noViable(k int) {
	p.unexpected(k)
	p.recovering = true
}

func (p *parser) mismatch(k int, expecting string) {
	p.failAt(k)
	if !p.recovering {
		t := p.tok(k)
		p.report(t.span, "mismatched input "+p.quoted(t)+" expecting "+expecting)
	}
	p.recovering = true
}

func (p *parser) missing(expected string) {
	p.failAt(1)
	if !p.recovering {
		t := p.tok(1)
		p.report(t.span, "missing "+expected+" at "+p.quoted(t))
	}
	p.recovering = true
}

// grammarError is an error alternative of the grammar itself: reported whatever the recovery
// state, and the file is still checked.
func (p *parser) grammarError(at span, msg string) {
	p.found = append(p.found, finding{at, msg})
}

// missingMatch is "Missing 'match' keyword before path.", which the compiler reports for any
// syntax error in a path, at the path's start. It stops the compiler.
func (p *parser) missingMatch(at span) {
	p.syntaxError = true
	p.grammarError(at, msgMissingMatch)
}

// expect matches one token with ANTLR's inline recovery: it deletes one extraneous token, or
// conjures the expected one up when the current token can follow it (ok and a nil token).
// It fails, in recovery mode, when neither works.
func (p *parser) expect(want tk, follows func(tk) bool) (t *lexeme, ok bool) {
	if p.la(1) == want {
		b := p.bump()
		return &b, true
	}
	if p.la(2) == want && p.la(1) != tkEOF {
		p.unexpected(1)
		p.skip()
		b := p.bump()
		return &b, true
	}
	if follows(p.la(1)) {
		p.missing(want.display())
		return nil, true
	}
	p.mismatch(1, want.display())
	return nil, false
}

// ----- declarations

func (p *parser) file() *file {
	f := &file{span: span{0, len(p.src)}}
	if p.la(1) == tkRulesVersion {
		p.version(f)
	}
	expecting := expectTop
	if p.kind[0] == tkRulesVersion {
		expecting = expectTopWithVersion
	}
	services := map[string]bool{}
	first := true // no declaration read yet
	for {
		switch p.la(1) {
		case tkFunction:
			if fn := p.function(nil); fn != nil {
				f.functions = append(f.functions, fn)
			}
		case tkImport:
			p.importDecl()
		case tkService:
			p.service(f, services)
		case tkEOF:
			if first {
				p.mismatch(1, expecting)
			}
			return f
		default:
			switch {
			case !first:
				p.unexpected(1)
				p.skip()
				p.skipUntil(tk.startsTop)
			case p.la(2).startsTop() && p.la(2) != tkEOF:
				p.unexpected(1)
				p.skip()
			default:
				p.mismatch(1, expecting)
				p.skipUntil(func(tk) bool { return false })
				return f
			}
			continue
		}
		first = false
	}
}

// version reads rules_version = '2';.
func (p *parser) version(f *file) {
	keyword := p.bump()
	_, ok := p.expect(tkAssign, func(t tk) bool { return t == tkString })
	var value *lexeme
	if ok {
		value, ok = p.expect(tkString, func(t tk) bool { return t == tkSemicolon || t.startsTop() })
	}
	if !ok {
		p.skipUntil(tk.startsTop)
		return
	}
	f.versionAt = keyword.span
	if value != nil {
		f.version = lexUnquote(p.text(*value))
	}
	if p.la(1) == tkSemicolon {
		p.bump()
	}
}

// importDecl reads import "x"; and refuses it.
func (p *parser) importDecl() {
	keyword := p.bump()
	if p.la(1) != tkString {
		p.noViable(1)
		p.skipUntil(tk.startsTop)
		return
	}
	module := lexUnquote(p.text(p.bump()))
	if p.la(1) == tkSemicolon {
		p.bump()
	}
	p.late = append(p.late, finding{keyword.span, msgImport},
		finding{keyword.span, fmt.Sprintf(msgImportModule, module)})
}

// service reads service name { … }. The tree holds the first service: another one with the
// same name is an error, and one with another name is read and left out.
func (p *parser) service(f *file, seen map[string]bool) {
	p.bump()
	if p.la(1) != tkIdent {
		p.noViable(1)
		p.skipUntil(tk.startsTop)
		return
	}
	start := p.tok(1).start
	name := p.text(p.bump())
	for p.la(1) == tkDot && p.la(2) == tkIdent {
		p.bump()
		name += "." + p.text(p.bump())
	}
	nameAt := p.from(start)
	if p.la(1) != tkLBrace {
		p.noViable(1)
		p.skipUntil(tk.startsTop)
		return
	}
	var body block
	switch t := p.la(2); {
	case t == tkRBrace:
		p.bump()
		p.grammarError(p.bump().span, msgEmptyService)
	case inService.starts(t):
		p.bump()
		body = p.body(inService)
	default:
		p.noViable(2)
		p.skipUntil(tk.startsTop)
		return
	}
	switch {
	case len(seen) == 0:
		f.service, f.serviceAt, f.body = name, nameAt, body
	case seen[name]:
		p.late = append(p.late, finding{nameAt, msgDuplicateService})
	}
	seen[name] = true
}

// body reads the declarations of a service or match block after its {, up to its }.
func (p *parser) body(pl place) block {
	var b block
	p.bodies++
	defer func() { p.bodies-- }()
	for {
		if p.bodies > parseMaxBodies {
			// Far deeper than the compiler accepts, which the checker reports: the rest of the
			// file is not read.
			p.gaveUp = true
			p.skipUntil(func(tk) bool { return false })
			return b
		}
		switch p.la(1) {
		case tkFunction:
			if fn := p.function(&pl); fn != nil {
				b.functions = append(b.functions, fn)
			}
		case tkMatch:
			if m := p.matchDecl(pl); m != nil {
				b.matches = append(b.matches, m)
			}
		case tkSegment, tkSlash:
			p.matchWithoutKeyword(pl)
		case tkAllow:
			if pl != inMatch {
				if p.badDeclaration(pl) {
					return b
				}
				continue
			}
			if a := p.allow(); a != nil {
				b.allows = append(b.allows, a)
			}
		case tkRBrace:
			p.bump()
			return b
		default:
			if p.badDeclaration(pl) {
				return b
			}
		}
	}
}

// badDeclaration skips what is no declaration, and reports whether the body's closing brace is
// missing.
func (p *parser) badDeclaration(pl place) bool {
	p.unexpected(1)
	p.skip()
	p.skipUntil(pl.stops)
	if t := p.la(1); t == tkEOF || t == tkImport || t == tkService {
		p.expect(tkRBrace, func(t tk) bool {
			return pl == inService && (t == tkEOF || t == tkImport || t == tkService || t == tkFunction)
		})
		return true
	}
	return false
}

// matchDecl reads match path { … }.
func (p *parser) matchDecl(pl place) *match {
	keyword := p.bump()
	if t := p.la(1); t != tkSegment && t != tkSlash {
		p.noViable(1)
		p.skipUntil(pl.stops)
		return nil
	}
	pathAt := p.tok(1).span
	m := &match{path: p.matchPath()}
	done := func() *match {
		m.span = p.from(keyword.start)
		return m
	}
	switch p.la(1) {
	case tkLBrace:
		switch t := p.la(2); {
		case inMatch.starts(t):
			p.bump()
			m.body = p.body(inMatch)
			return done()
		case t == tkRBrace:
			p.bump()
			p.grammarError(p.bump().span, msgEmptyMatch)
			return done()
		}
		p.missingMatch(pathAt)
		p.bump()
		p.unexpected(1)
		if p.la(1) != tkEOF && p.la(2) == tkRBrace {
			p.unexpected(1)
			p.skip()
			p.bump()
			return done()
		}
		p.mismatch(1, expectPathNext)
		p.skipUntil(pl.stops)
		return nil
	case tkRBrace:
		p.missingMatch(pathAt)
		p.unexpected(1)
		p.missing(tkLBrace.display())
		p.bump()
		return done()
	}
	p.missingMatch(pathAt)
	p.unexpected(1)
	p.mismatch(1, expectPathNext)
	p.skipUntil(pl.stops)
	return nil
}

// matchWithoutKeyword reads a path where a declaration is expected: the grammar takes it as a
// match without its keyword, followed by { and }.
func (p *parser) matchWithoutKeyword(pl place) {
	p.missingMatch(p.tok(1).span)
	p.matchPath()
	if p.la(1) != tkLBrace {
		p.mismatch(1, expectPathNext)
		p.skipUntil(pl.stops)
		return
	}
	p.bump()
	switch {
	case p.la(1) == tkRBrace:
		p.bump()
	case p.la(1) != tkEOF && p.la(2) == tkRBrace:
		p.unexpected(1)
		p.skip()
		p.bump()
	case pl.starts(p.la(1)):
		p.missing(tkRBrace.display())
	default:
		p.mismatch(1, tkRBrace.display())
		p.skipUntil(pl.stops)
	}
}

// matchPath reads the segments of a match path: /literal, /{x}, /{x=*} and /{x=**}.
func (p *parser) matchPath() []pattern {
	var path []pattern
	for {
		switch p.la(1) {
		case tkSegment:
			t := p.bump()
			path = append(path, pattern{span: t.span, kind: patternLiteral, text: p.src[t.start+1 : t.end]})
		case tkSlash:
			slash := p.bump()
			if seg, ok := p.binding(slash.start); ok {
				path = append(path, seg)
			} else {
				p.grammarError(slash.span, msgSlashInPath)
			}
		default:
			return path
		}
	}
}

// binding reads {x}, {x=*} or {x=**} after a slash.
func (p *parser) binding(start int) (pattern, bool) {
	if p.la(1) != tkLBrace || p.la(2) != tkIdent {
		return pattern{}, false
	}
	n, kind := 0, patternVariable
	switch {
	case p.la(3) == tkRBrace:
		n = 3
	case p.la(3) == tkAssign && token(p.la(4)) == tokStar && p.la(5) == tkRBrace:
		n = 5
	case p.la(3) == tkAssign && token(p.la(4)) == tokStar && token(p.la(5)) == tokStar && p.la(6) == tkRBrace:
		n, kind = 6, patternRest
	default:
		return pattern{}, false
	}
	name := p.text(p.tok(2))
	for range n {
		p.bump()
	}
	return pattern{span: p.from(start), kind: kind, text: name}, true
}

// patternNameAt returns where the name of a variable segment is, {x} or {x=**}: the first
// identifier in its span. The checker reports a duplicate variable there, and a misplaced
// recursive wildcard at the segment's span.
func patternNameAt(src string, pt pattern) span {
	if pt.kind == patternLiteral {
		return pt.span
	}
	toks, _ := lex(src[pt.start:pt.end])
	for _, t := range toks {
		if t.kind == lexIdent {
			return span{pt.start + t.start, pt.start + t.end}
		}
	}
	return pt.span
}

// allow reads allow methods: if condition;, with the grammar's own errors for the common
// mistakes.
func (p *parser) allow() *allow {
	keyword := p.bump()
	stops := inMatch.stops
	if p.la(1) != tkIdent {
		if t := p.la(1); t == tkColon || t == tkIf {
			p.grammarError(p.tok(1).span, msgNoOperation)
		}
		p.noViable(1)
		p.skipUntil(stops)
		return nil
	}
	a := &allow{}
	for {
		t := p.bump()
		a.methods = append(a.methods, name{t.span, p.text(t)})
		if p.la(1) != tkComma {
			break
		}
		if p.la(2) != tkIdent {
			p.noViable(1)
			p.skipUntil(stops)
			return nil
		}
		p.bump()
	}
	switch t := p.la(1); {
	case t == tkColon:
		p.bump()
		switch t := p.la(1); {
		case t == tkIf:
			p.bump()
			a.cond = p.condition()
		case t.startsExpression():
			p.grammarError(p.tok(1).span, msgMissingIf)
			a.cond = p.statement(stops)
		default:
			p.noViable(1)
			p.skipUntil(stops)
			return nil
		}
	case t == tkIf:
		p.grammarError(p.tok(1).span, msgMissingColon)
		p.bump()
		a.cond = p.condition()
	case t == tkSemicolon || stops(t):
	default:
		p.noViable(1)
		p.skipUntil(stops)
		return nil
	}
	if p.la(1) == tkSemicolon {
		p.bump()
	}
	a.span = p.from(keyword.start)
	return a
}

// condition reads the expression after if. A missing one is an error, and the statement then
// holds false, never no condition, which would grant.
func (p *parser) condition() expr {
	if p.la(1).startsExpression() {
		return p.statement(inMatch.stops)
	}
	p.grammarError(p.tok(1).span, msgMissingCondition)
	return &litExpr{span: p.tok(1).span, val: Bool(false)}
}

// function reads function name(params) { let …; return …; }. pl is nil at the top of the file.
func (p *parser) function(pl *place) *function {
	keyword := p.bump()
	stops := tk.startsTop
	if pl != nil {
		stops = pl.stops
	}
	fn := &function{}
	// The grammar's errors for a missing name (before the parameters) and a missing parameter
	// list; the rest is read.
	switch p.la(1) {
	case tkIdent:
		t := p.bump()
		fn.name = name{t.span, p.text(t)}
	case tkLParen:
		p.grammarError(p.tok(1).span, msgFunctionNoID)
		fn.name = name{span: p.tok(1).span}
	default:
		p.noViable(1)
		p.skipUntil(stops)
		return nil
	}
	switch {
	case p.la(1) != tkLParen:
		p.grammarError(p.tok(1).span, msgFunctionNoSig)
	case p.la(2) == tkRParen:
		p.bump()
		p.bump()
	default:
		p.bump()
		for {
			if p.la(1) != tkIdent {
				p.noViable(1)
				p.skipUntil(stops)
				return nil
			}
			t := p.bump()
			fn.params = append(fn.params, name{t.span, p.text(t)})
			if p.la(1) == tkRParen {
				p.bump()
				break
			}
			if p.la(1) != tkComma {
				p.noViable(1)
				p.skipUntil(stops)
				return nil
			}
			p.bump()
		}
	}
	if p.la(1) != tkLBrace {
		p.noViable(1)
		p.skipUntil(stops)
		return nil
	}
	p.bump()
	if p.la(1) == tkRBrace {
		closing := p.bump()
		p.grammarError(closing.span, msgFunctionNoBody)
		fn.ret = &litExpr{span: closing.span, val: Null()}
		fn.span = p.from(keyword.start)
		return fn
	}
	for p.la(1) == tkLet {
		fn.lets = append(fn.lets, p.letBinding())
	}
	if p.la(1) == tkRBrace && len(fn.lets) > 0 {
		// As measured: the brace is reported twice, the second time as if a let's value went
		// on, and it closes the function.
		p.unexpected(1)
		p.mismatch(1, expectAfterLetValue)
		closing := p.bump()
		fn.ret = &litExpr{span: closing.span, val: Null()}
		fn.span = p.from(keyword.start)
		return fn
	}
	if p.la(1) != tkReturn {
		p.noViable(1)
		p.skipUntil(stops)
		return nil
	}
	p.bump()
	if p.la(1).startsExpression() {
		fn.ret = p.statement(stops)
	} else {
		fn.ret = p.missingOperand(expectExpression)
	}
	if p.la(1) == tkSemicolon {
		p.bump()
	}
	switch {
	case p.la(1) == tkRBrace:
		p.bump()
	case p.la(1) != tkEOF && p.la(2) == tkRBrace:
		p.unexpected(1)
		p.skip()
		p.bump()
	default:
		p.mismatch(1, tkRBrace.display())
		p.skipUntil(stops)
	}
	fn.span = p.from(keyword.start)
	return fn
}

// letBinding reads let name = value;.
func (p *parser) letBinding() *let {
	keyword := p.bump()
	l := &let{}
	if p.la(1) == tkIdent {
		t := p.bump()
		l.name = name{t.span, p.text(t)}
	} else {
		l.name = name{span: p.tok(1).span}
		p.mismatch(1, tkIdent.display())
	}
	p.expect(tkAssign, tk.startsExpression)
	if p.la(1).startsExpression() {
		l.value = p.statement(func(t tk) bool {
			return t == tkLet || t == tkReturn || t == tkRBrace || t == tkSemicolon || t == tkEOF
		})
	} else {
		l.value = p.missingOperand(expectExpression)
	}
	p.expect(tkSemicolon, func(t tk) bool { return t == tkLet || t == tkReturn })
	l.span = p.from(keyword.start)
	return l
}

// ----- expressions

// statement reads the expression of a statement; after an error inside brackets, it skips to
// what stops the statement.
func (p *parser) statement(stops func(tk) bool) expr {
	e := p.expression()
	if p.abort {
		p.abort = false
		p.skipUntil(stops)
	}
	p.roots = append(p.roots, e)
	return e
}

func (p *parser) expression() expr { return p.nested(p.ternary) }

// nested parses one level deeper. Past parseMaxNesting the statement is given up, and the depth
// check reports it.
func (p *parser) nested(parse func() expr) expr {
	if p.nest >= parseMaxNesting {
		p.abort = true
		return p.placeholder()
	}
	p.nest++
	defer func() { p.nest-- }()
	return parse()
}

// placeholder stands for an expression that could not be read.
func (p *parser) placeholder() expr { return &litExpr{span: p.tok(1).span, val: Null()} }

// tooComplex gives the statement up: an expression too long to keep.
func (p *parser) tooComplex() {
	p.grammarError(p.tok(1).span, msgTooComplex)
	p.abort = true
}

func (p *parser) ternary() expr {
	test := p.operators(1)
	if p.abort || p.la(1) != tkQuestion {
		return test
	}
	p.bump()
	yes := p.expression()
	if p.abort {
		return &condExpr{span: p.from(test.pos().start), test: test, yes: yes, no: p.placeholder()}
	}
	switch {
	case p.la(1) == tkColon:
		p.bump()
	case p.la(1).startsExpression():
		p.missing(tkColon.display())
	default:
		p.mismatch(1, expectAfterThen)
		return test
	}
	no := p.expression()
	return &condExpr{span: span{test.pos().start, max(test.pos().end, no.pos().end)}, test: test, yes: yes, no: no}
}

// precedence returns the level of a binary operator, or of is, from the loosest (1); 0 is no
// operator.
func (t tk) precedence() int {
	switch t {
	case tk(tokOr):
		return 1
	case tk(tokAnd):
		return 2
	case tkIn:
		return 3
	case tkIs:
		return 4
	case tk(tokEQ), tk(tokNE):
		return 5
	case tk(tokLT), tk(tokLE), tk(tokGT), tk(tokGE):
		return 6
	case tk(tokPlus), tk(tokMinus):
		return 7
	case tk(tokStar), tk(tokSlash), tk(tokPercent):
		return 8
	}
	return 0
}

// operators reads operands joined by operators of level lowest or tighter, left-associative: the
// right operand of an operator holds only tighter ones.
func (p *parser) operators(lowest int) expr {
	x := p.unary()
	for n := 0; !p.abort; n++ {
		t := p.la(1)
		prec := t.precedence()
		if prec == 0 || prec < lowest {
			break
		}
		if n == parseMaxOperators {
			// Far deeper than the compiler accepts; the depth check reports it.
			p.abort = true
			break
		}
		op := p.bump()
		if t == tkIs {
			x = p.isType(x)
			continue
		}
		y := p.operand(func() expr { return p.operators(prec + 1) })
		opTok := op.op
		if t == tkIn {
			opTok = tokIn
		}
		x = &binaryExpr{span: span{x.pos().start, max(x.pos().end, y.pos().end)}, op: opTok, x: x, y: y}
	}
	return x
}

// isType reads the type after is. An unknown type is the grammar's error, at the token after it.
func (p *parser) isType(x expr) expr {
	t := p.tok(1)
	typ := ""
	switch k := p.la(1); {
	case k == tkIdent:
		p.bump()
		typ = p.text(t)
	case !k.startsExpression():
		p.missing(tkIdent.display())
		typ = "<missing IDENTIFIER>"
	default:
		p.mismatch(1, tkIdent.display())
		p.skip()
		typ = p.text(t)
	}
	if !slices.Contains(parseIsTypes, typ) {
		p.grammarError(p.tok(1).span, fmt.Sprintf(msgIsType, typ, strings.Join(parseIsTypes, ",")))
	}
	return &isExpr{span: p.from(x.pos().start), x: x, typ: typ, typAt: t.span}
}

// operand reads an operand after an operator: when the token cannot start one but the next can,
// the token is extraneous.
func (p *parser) operand(next func() expr) expr {
	if p.la(1).startsExpression() {
		return next()
	}
	if p.la(1) != tkEOF && p.la(2).startsExpression() {
		p.unexpected(1)
		p.skip()
		return next()
	}
	return p.missingOperand(expectExpression)
}

// missingOperand reports no operand where one is required. Inside brackets the compiler fails
// the whole statement ("Unexpected"); elsewhere it expects an expression.
func (p *parser) missingOperand(expecting string) expr {
	ph := p.placeholder()
	if p.nesting > 0 {
		p.noViable(1)
		p.abort = true
		return ph
	}
	p.mismatch(1, expecting)
	p.skipUntil(func(t tk) bool {
		switch t {
		case tkSemicolon, tkRBrace, tkRParen, tkRBrack, tkComma, tkColon, tkAllow, tkMatch, tkFunction, tkLet, tkReturn, tkEOF:
			return true
		}
		return t.binaryOp()
	})
	return ph
}

func (p *parser) unary() expr {
	start := p.tok(1).start
	switch p.la(1) {
	case tkNot:
		p.bump()
		x := p.nested(func() expr { return p.operand(p.unary) })
		return &unaryExpr{span: p.from(start), op: tokNot, x: x}
	case tkMinus:
		p.bump()
		// -9223372036854775808 is a literal, not the negation of one out of range.
		if p.la(1) == tkInt && p.text(p.tok(1)) == "9223372036854775808" && p.la(2) != tkDot && p.la(2) != tkLBrack {
			p.bump()
			return &litExpr{span: p.from(start), val: Int(math.MinInt64)}
		}
		var x expr
		if p.la(1).startsPrimary() {
			x = p.postfix()
		} else {
			x = p.missingOperand(expectNegated)
		}
		return &unaryExpr{span: p.from(start), op: tokMinus, x: x}
	case tkDecrement, tkIncrement:
		p.bump()
		valid := p.la(1).startsPrimary()
		// Inside brackets that then fail to parse, ANTLR's prediction fails before the
		// grammar's error is reached.
		if valid || p.nesting == 0 {
			p.grammarError(p.tok(1).span, msgIncrement)
		}
		if !valid {
			p.noViable(1)
			return p.placeholder()
		}
		return p.postfix()
	}
	return p.postfix()
}

// postfix reads a primary and the member accesses, calls, indexes and slices after it.
func (p *parser) postfix() expr {
	x := p.primary()
	for n := 0; !p.abort; n++ {
		if t := p.la(1); t != tkDot && t != tkLBrack {
			return x
		}
		if n >= p.lim.MemberChain {
			p.tooComplex()
			return x
		}
		start := x.pos().start
		if p.la(1) == tkDot {
			// A field may be named by any word but rules_version; a method only by an
			// identifier.
			if !p.la(2).isWord() || p.la(2) == tkRulesVersion {
				p.bump()
				p.noViable(1)
				return x
			}
			p.bump()
			if p.la(1) != tkIdent && p.la(2) == tkLParen {
				// ANTLR fails at the parenthesis before it matches the keyword.
				p.noViable(2)
				return x
			}
			t := p.bump()
			x = &memberExpr{span: p.from(start), x: x, name: p.text(t), nameAt: t.span}
			if p.la(1) == tkLParen {
				p.bump()
				args := p.items(tkRParen)
				x = &callExpr{span: p.from(start), fn: x, args: args}
			}
			continue
		}
		p.bump()
		p.nesting++
		i := p.operand(p.expression)
		var hi expr
		if p.la(1) == tkColon && !p.abort {
			p.bump()
			hi = p.operand(p.expression)
		}
		p.close(tkRBrack)
		p.nesting--
		if hi != nil {
			x = &sliceExpr{span: p.from(start), x: x, lo: i, hi: hi}
		} else {
			x = &indexExpr{span: p.from(start), x: x, i: i}
		}
	}
	return x
}

// close matches a closing token: an extraneous token before it is deleted; otherwise its
// absence is "Unexpected" (ANTLR finds no viable alternative there).
func (p *parser) close(want tk) {
	switch {
	case p.abort:
	case p.la(1) == want:
		p.bump()
	case p.la(1) != tkEOF && p.la(2) == want:
		p.unexpected(1)
		p.skip()
		p.bump()
	default:
		p.noViable(1)
	}
}

// items reads expressions separated by commas up to closing (a trailing comma is allowed),
// after the opening token.
func (p *parser) items(closing tk) []expr {
	p.nesting++
	defer func() { p.nesting-- }()
	var items []expr
	for p.la(1) != closing {
		items = append(items, p.operand(p.expression))
		if p.la(1) != tkComma || p.abort {
			break
		}
		p.bump()
	}
	p.close(closing)
	return items
}

func (p *parser) primary() expr {
	t := p.tok(1)
	switch p.la(1) {
	case tkNull:
		p.bump()
		return &litExpr{span: t.span, val: Null()}
	case tkTrue, tkFalse:
		v := p.la(1) == tkTrue
		p.bump()
		return &litExpr{span: t.span, val: Bool(v)}
	case tkInt:
		p.bump()
		n, err := strconv.ParseInt(p.text(t), 10, 64)
		if err != nil {
			p.late = append(p.late, finding{t.span, fmt.Sprintf(msgInvalidNumber, p.text(t))})
		}
		return &litExpr{span: t.span, val: Int(n)}
	case tkFloat:
		p.bump()
		// Out of range is ±Inf, as Java reads it.
		f, _ := strconv.ParseFloat(p.text(t), 64)
		return &litExpr{span: t.span, val: Float(f)}
	case tkString:
		p.bump()
		return &litExpr{span: t.span, val: String(lexUnquote(p.text(t)))}
	case tkBytes:
		p.bump()
		return &litExpr{span: t.span, val: Bytes([]byte(lexUnquote(p.text(t))))}
	case tkUnpairedSingle, tkUnpairedDouble:
		p.bump()
		// Inside brackets, which an unclosed string cannot close, ANTLR's prediction fails
		// first and the grammar's error is not reached.
		if p.nesting == 0 {
			p.grammarError(p.tok(1).span, fmt.Sprintf(msgUnclosedString, p.src[t.start]))
		}
		return &litExpr{span: t.span, val: String("")}
	case tkIdent:
		p.bump()
		id := &identExpr{span: t.span, name: p.text(t)}
		if p.la(1) != tkLParen {
			return id
		}
		p.bump()
		args := p.items(tkRParen)
		return &callExpr{span: p.from(t.start), fn: id, args: args}
	case tkLParen:
		// The expression keeps its own span, and the parenthesis is kept aside for the depth
		// check.
		p.bump()
		p.nesting++
		x := p.operand(p.expression)
		p.close(tkRParen)
		p.nesting--
		p.parens[x] = append([]span{t.span}, p.parens[x]...)
		return x
	case tkLBrack:
		p.bump()
		return &listExpr{elems: p.items(tkRBrack), span: p.from(t.start)}
	case tkLBrace:
		p.bump()
		keys, vals := p.entries()
		return &mapExpr{span: p.from(t.start), keys: keys, vals: vals}
	case tkSegment, tkSlash:
		return p.path()
	}
	return p.missingOperand(expectExpression)
}

// entries reads key: value, … up to }, after the {.
func (p *parser) entries() (keys, vals []expr) {
	p.nesting++
	defer func() { p.nesting-- }()
	for p.la(1) != tkRBrace {
		k := p.operand(p.expression)
		if p.abort {
			return keys, vals
		}
		switch {
		case p.la(1) == tkColon:
			p.bump()
		case p.la(1) != tkEOF && p.la(2) == tkColon:
			p.unexpected(1)
			p.skip()
			p.bump()
		default:
			p.noViable(1)
			p.abort = true
			return keys, vals
		}
		v := p.operand(p.expression)
		keys, vals = append(keys, k), append(vals, v)
		if p.la(1) != tkComma || p.abort {
			break
		}
		p.bump()
	}
	p.close(tkRBrace)
	return keys, vals
}

// path reads a path literal: /segment and /$(x).
func (p *parser) path() expr {
	first := p.tok(1)
	pe := &pathExpr{}
loop:
	for {
		switch {
		case p.la(1) == tkSegment:
			t := p.bump()
			pe.segs = append(pe.segs, pathSeg{span: t.span, text: p.src[t.start+1 : t.end]})
		case p.la(1) == tkSlash && p.la(2) == tkDollar && p.la(3) == tkLParen:
			slash := p.bump()
			p.bump()
			p.bump()
			p.nesting++
			x := p.operand(p.expression)
			p.nesting--
			if p.abort {
				pe.segs = append(pe.segs, pathSeg{span: p.from(slash.start), x: x})
				break loop
			}
			if p.la(1) != tkRParen {
				p.missingMatch(first.span)
				p.noViable(1)
				pe.segs = append(pe.segs, pathSeg{span: p.from(slash.start), x: x})
				break loop
			}
			p.bump()
			pe.segs = append(pe.segs, pathSeg{span: p.from(slash.start), x: x})
		case p.la(1) == tkSlash:
			p.grammarError(p.bump().span, msgSlashInPath)
		default:
			break loop
		}
	}
	pe.span = p.from(first.start)
	return pe
}

// ----- the depth check

// checkDepth reports "Expression is too complex to evaluate safely." at every expression, and
// every parenthesis, nested exactly lim.ExpressionDepth+1 deep in a statement's expression,
// counting from 0 at the statement. Every operand, argument, index, element, key, value, branch
// and parenthesis is one level deeper; an accessed value and a method's receiver are not, and
// -(x) is one level, not two (hidane's measurements). Without recursion: a chain of operators
// can be thousands deep.
func (p *parser) checkDepth(root expr) {
	limit := p.lim.ExpressionDepth + 1
	type item struct {
		e       expr
		level   int
		negated bool
	}
	stack := []item{{root, 0, false}}
	for len(stack) > 0 {
		it := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		parens := p.parens[it.e]
		if it.negated && len(parens) > 0 {
			parens = parens[1:]
		}
		level := it.level
		for _, at := range parens {
			if level == limit {
				p.late = append(p.late, finding{at, msgTooComplex})
			}
			level++
		}
		if level == limit {
			p.late = append(p.late, finding{it.e.pos(), msgTooComplex})
		}
		if level > limit {
			continue // reported at its ancestor of the limit's depth
		}
		// The children, pushed last first so that they come out in source order.
		var children []item
		deeper := func(es ...expr) {
			for _, e := range es {
				if e != nil {
					children = append(children, item{e, level + 1, false})
				}
			}
		}
		same := func(e expr) { children = append(children, item{e, level, false}) }
		switch e := it.e.(type) {
		case *listExpr:
			deeper(e.elems...)
		case *mapExpr:
			for i := range e.keys {
				deeper(e.keys[i], e.vals[i])
			}
		case *pathExpr:
			for _, s := range e.segs {
				deeper(s.x)
			}
		case *memberExpr:
			same(e.x)
		case *indexExpr:
			same(e.x)
			deeper(e.i)
		case *sliceExpr:
			same(e.x)
			deeper(e.lo, e.hi)
		case *callExpr:
			if m, ok := e.fn.(*memberExpr); ok {
				if id, ok := m.x.(*identExpr); !ok || !parsePackages[id.name] || len(p.parens[id]) > 0 {
					same(m.x)
				}
			}
			deeper(e.args...)
		case *unaryExpr:
			children = append(children, item{e.x, level + 1, e.op == tokMinus})
		case *binaryExpr:
			deeper(e.x, e.y)
		case *isExpr:
			deeper(e.x)
		case *condExpr:
			deeper(e.test, e.yes, e.no)
		}
		for i := len(children) - 1; i >= 0; i-- {
			stack = append(stack, children[i])
		}
	}
}
